function preloadBackgroundImage(url) {
  return new Promise((resolve, reject) => {
      const img = new Image();
      img.src = url;
      img.onload = resolve;
      img.onerror = reject;
  });
}
document.addEventListener('DOMContentLoaded', function () {
    const button = document.querySelector('.button');
    const fullNameInput = document.querySelector('input[name="fullName"]');
    const passwordInput = document.querySelector('input[name="password"]');
    const errorDiv = document.querySelector('.error');
  const preloader = document.getElementById('preloader');
setTimeout(() => {
preloader.classList.add('show'); 

}, 2000); 
    function attemptLogin() {
      const fullName = fullNameInput.value.trim();
      const password = passwordInput.value.trim();
  
      if (!fullName || !password) {
        errorDiv.textContent = 'Заполните все поля!';
        errorDiv.style.visibility = 'visible';
        return;
      }
  
      fetch('/login', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          fullName,
          password
        })
      })
      .then(response => {
        if (!response.ok) throw new Error('Неверный логин или пароль!');
        return response.json();
      })
      .then(data => {
        if (data.role) {
          const redirectUrl = data.role === 'admin'
            ? '/Administrator/Administratormainmenu/html/amainmenu.html'
            : '/User/Usermainmenu/html/umainmenu.html';
          window.location.href = redirectUrl;
        } else {
          throw new Error('Неверный логин или пароль!');
        }
      })
      .catch(err => {
        errorDiv.textContent = err.message || 'Ошибка при входе!';
        errorDiv.style.visibility = 'visible';
      });
    }
    const backgroundImage = preloadBackgroundImage("/Projectresources/Skypicture.jpg");
    Promise.all([backgroundImage])
    .then(() => {
        preloader.remove();
        document.body.style.visibility = 'visible';
    })
    .catch(error => {
        console.error('Ошибка при загрузке:', error);
        preloader.remove();
        document.body.style.visibility = 'visible';
    });
    // Прячем ошибку при вводе
    fullNameInput.addEventListener('input', () => {
      errorDiv.style.visibility = 'hidden';
    });
    passwordInput.addEventListener('input', () => {
      errorDiv.style.visibility = 'hidden';
    });
  
    button.addEventListener('click', attemptLogin);
  
    document.addEventListener('keydown', function (e) {
      if (e.key === 'Enter') {
        attemptLogin();
      }
    });
  
    document.querySelector('.clickable-footer').addEventListener('click', function () {
      const fileName = 'Пользовательское соглашение.txt';
      const link = document.createElement('a');
      link.href = '/Projectresources/' + fileName;
      link.download = fileName;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
    });
  });